declare(strict_types=1);
namespace OCA\Placetel\Native;

/** Contact changes require an explicit action and a fresh provider snapshot. */
final class Phonebook {
 private const FIELDS=['speeddial','first_name','last_name','email','email_work','company','address','address_work','phone_work','mobile_work','phone','mobile','fax','fax_work','facebook_url','linkedin_url','xing_url','twitter_account','color','tags','user_id','blocked'];
 private const EDIT=['first_name','last_name','company','phone_work','mobile_work','phone','mobile','email','email_work'];
 public function __construct(private Store $store,private Api $api) {}
 private function id(mixed $v): string {if(!(is_string($v)||is_int($v))||!ctype_digit((string)$v)||(int)$v<1||(float)$v>2147483647)throw new \InvalidArgumentException('Ungültige Kontakt-ID.');return (string)(int)$v;}
 private function wait(): void {$delay=(float)$this->store->get('api:next',0)-microtime(true);if($delay>2)throw new RemoteException('Placetel begrenzt die Abrufrate. Bitte später erneut versuchen.',429);if($delay>0)usleep((int)ceil($delay*1000000)+1000);}
 private function live(): void {if($this->store->get('mode','demo')!=='live')throw new \InvalidArgumentException('Telefonbuchverwaltung ist nur im Echtbetrieb verfügbar.');}
 private function version(array $row): string {ksort($row);return hash('sha256',json_encode($row,JSON_THROW_ON_ERROR));}
 private function safe(array $row): array {$id=$this->id($row['id']??null);$result=['id'=>$id,'version'=>$this->version($row)];foreach(self::EDIT as $field){$value=$row[$field]??'';$result[$field]=is_string($value)?$value:'';}return $result;}
 public function page(mixed $page): array {$this->live();if(!(is_string($page)||is_int($page))||!ctype_digit((string)$page)||(int)$page<1||(int)$page>1000)throw new \InvalidArgumentException('Ungültige Seite.');$page=(int)$page;$rows=$this->api->page('/contacts',$page);return ['contacts'=>array_map(fn($r)=>$this->safe($r),$rows),'page'=>$page,'more'=>count($rows)>0&&$page<1000];}
 private function read(string $id): array {$this->wait();$row=$this->api->placetel('/contacts/'.$id);if(!is_array($row)||$this->id($row['id']??null)!==$id)throw new RemoteException('Kontakt konnte nicht sicher geladen werden.');return $row;}
 private function fields(mixed $input,bool $requireName=true): array {if(!is_array($input)||array_diff(array_keys($input),self::EDIT))throw new \InvalidArgumentException('Ungültige Kontaktfelder.');$out=[];foreach($input as $key=>$value){if(!is_string($value)||mb_strlen($value)>500||preg_match('/[\x00-\x1f\x7f]/',$value))throw new \InvalidArgumentException('Kontaktfeld ungültig oder zu lang.');$out[$key]=trim($value);}if($requireName&&!trim(($out['first_name']??'').($out['last_name']??'').($out['company']??'')))throw new \InvalidArgumentException('Bitte Namen oder Firma eingeben.');foreach(['email','email_work'] as $key)if(($out[$key]??'')!==''&&!filter_var($out[$key],FILTER_VALIDATE_EMAIL))throw new \InvalidArgumentException('Bitte eine gültige E-Mail-Adresse eingeben.');return $out;}
 private function invalidate(): void {$this->store->put('live:contactsAtEpoch',0);$job=$this->store->get('sync:job');if(is_array($job)&&($job['kind']??null)==='contacts')$this->store->remove('sync:job');}
 public function change(array $input): array {$this->live();$operation=$input['operation']??null;if(!in_array($operation,['create','update','delete'],true))throw new \InvalidArgumentException('Ungültige Kontaktaktion.');
  if($operation==='create'){$data=$this->fields($input['contact']??null);$this->wait();$this->invalidate();$result=$this->api->placetel('/contacts','POST',$data);if(!is_array($result)||!isset($result['id']))throw new RemoteException('Kontaktanlage nicht bestätigt. Bitte Telefonbuch prüfen; nicht automatisch wiederholen.');}
  else {$id=$this->id($input['id']??null);$old=$this->read($id);$version=$input['version']??null;if(!is_string($version)||!hash_equals($this->version($old),$version))throw new \InvalidArgumentException('Kontakt wurde zwischenzeitlich geändert. Bitte neu laden.');$this->wait();$this->invalidate();if($operation==='delete'){$this->api->placetel('/contacts/'.$id,'DELETE');}else{$changes=$this->fields($input['contact']??null,false);if(!$changes)throw new \InvalidArgumentException('Keine Änderungen angegeben.');$body=array_replace(array_intersect_key($old,array_flip(self::FIELDS)),$changes);if(!trim((string)($body['first_name']??'').(string)($body['last_name']??'').(string)($body['company']??'')))throw new \InvalidArgumentException('Bitte Namen oder Firma eingeben.');$result=$this->api->placetel('/contacts/'.$id,'PUT',$body);if(!is_array($result)||$this->id($result['id']??null)!==$id)throw new RemoteException('Kontaktänderung nicht bestätigt. Bitte Telefonbuch prüfen; nicht automatisch wiederholen.');foreach($changes as $key=>$value)if(!array_key_exists($key,$result)||$result[$key]!==$value)throw new RemoteException('Kontaktänderung nicht vollständig bestätigt. Bitte Telefonbuch prüfen; nicht automatisch wiederholen.');}}
  $this->store->log('live','phonebook','Telefonbuchänderung bestätigt: '.$operation.'.','ok');return ['ok'=>true];
 }
}
